/* Ajuda de Boa 2.0 · 360X — interface local. Nenhum estado do navegador é tratado
   como confirmação bancária. Fontes oficiais e registros autodeclarados são distintos.
   2.0: Pix rápido com conferência anti-golpe, perspectivas e projetos, XP da Boa Ação
   (mesma régua do Placar XP da Bolsa Ajuda de Boa) e download do app Bolsa Ajuda de Boa. */
(function(){
'use strict';
const C=window.BA360,V=window.BA360_VAULT,DATA=window.BA360_CATALOG,X=window.BA360_XP;
const VITRINE=document.documentElement.dataset.mode==='vitrine';
const $=s=>document.querySelector(s),e=C.esc;
const cats=[['all','✳','Todas as causas'],['animais','🐾','Animais'],['plantas','🌱','Plantas e florestas'],['oceanos','🌊','Oceanos e águas'],['saude','✚','Saúde'],['infancia','🧸','Infância'],['alimentacao','🥣','Alimentação'],['acolhimento','🏡','Acolhimento'],['comunidades','🤝','Comunidades']];
const methods={dinheiro:'Doação financeira',voluntariado:'Voluntariado',materiais:'Materiais',divulgacao:'Divulgação',sangue:'Doação de sangue'};
const kindLabel={dinheiro:'Ajuda financeira',materiais:'Doação de materiais',tempo:'Tempo / voluntariado',sangue:'Doação de sangue',divulgacao:'Divulgação da causa'};
let category='all',query='',region='all',method='all',sort='ceara',view='explorar',period='all',favorites=new Set(),cart=new Map();
let toastTimer,pendingRecord=null,pendingImport=null,hasVault=false,lastActivity=Date.now(),walletRenderId=0;
const dialog=$('#dialog'),content=$('#dialog-content');
const cause=id=>DATA.find(c=>c.id===id);
const planKey='shop-ajuda-de-boa.plan.v1';
let planToken=null,planStorage=null;try{planStorage=localStorage;}catch{}
const planStore=window.BA360_PLAN.create({storage:planStorage,key:planKey,ids:DATA.map(c=>c.id),maxCents:C.MAX_CENTS,newRevision:()=>crypto.randomUUID(),lock:navigator.locks?.request?fn=>navigator.locks.request(planKey,{mode:'exclusive'},fn):null});
function applyPlan(snapshot){favorites=new Set(snapshot.state.favorites);cart=new Map(snapshot.state.cart);planToken=snapshot.token;}
try{applyPlan(planStore.load());}catch{}
async function savePlan(){try{const result=await planStore.save({favorites:[...favorites],cart:[...cart]},planToken);if(result.status==='conflict'){applyPlan(result);toast('O planejamento mudou em outra aba. A versão mais recente foi carregada; confira e repita sua alteração.',true);return false;}if(result.status==='unavailable'){toast('Neste navegador, o planejamento fica apenas nesta sessão. A gravação entre abas exige armazenamento local e Web Locks.',true);return false;}applyPlan(result);return true;}catch{toast('O navegador não permitiu salvar o planejamento. Mantenha esta página aberta.',true);return false;}}
window.addEventListener('storage',event=>{if(event.key!==planKey&&event.key!==null)return;try{applyPlan(planStore.load());renderRoute();toast('Planejamento atualizado por outra aba. Confira a cesta e os favoritos.');}catch{toast('Não foi possível atualizar o planejamento de outra aba. Recarregue a página antes de editar.',true);}});

const norm=s=>String(s).normalize('NFD').replace(/[̀-ͯ]/g,'').toLowerCase();
const today=()=>{const d=new Date();return `${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,'0')}-${String(d.getDate()).padStart(2,'0')}`;};
const day=s=>s.split('-').reverse().join('/');
const fresh=c=>{const elapsed=Date.now()-Date.parse(c.checked+'T00:00:00Z');return elapsed>=-86400000&&elapsed<=30*86400000;};
/* Conferência anti-golpe do doador: a chave do catálogo foi conferida por você no site oficial.
   Vale 30 dias, só neste navegador, e só para a mesma chave. Não substitui a conferência do banco. */
const checkKey='shop-ajuda-de-boa.checks.v1';let donorChecks={};try{donorChecks=JSON.parse(localStorage.getItem(checkKey)||'{}')||{};}catch{}
const donorFresh=c=>{const d=donorChecks[c.id];if(!c.pix||!d||d.key!==c.pix.key)return false;const el=Date.now()-Date.parse(d.at);return el>=0&&el<=30*86400000;};
const pixReady=c=>!!c.pix&&(fresh(c)||donorFresh(c));
function saveDonorCheck(c){donorChecks[c.id]={key:c.pix.key,at:new Date().toISOString()};try{localStorage.setItem(checkKey,JSON.stringify(donorChecks));}catch{toast('A conferência vale só enquanto esta página estiver aberta: o navegador não permitiu salvar.',true);}}
const pixLabel=c=>!c.pix?'Canal oficial':fresh(c)?'Pix · fonte recente':donorFresh(c)?'Pix · conferido por você':'Pix · conferir chave';
const moneyInput=n=>(n/100).toFixed(2).replace('.',',');
const ext=(url,text,cls='')=>`<a class="${e(cls)}" href="${e(url)}" target="_blank" rel="noopener noreferrer">${e(text)} ↗</a>`;
function bigCents(value){const s=String(value??'').trim().replace(/^R\$\s*/,'');if(!s)return null;let t;if(/^\d{1,3}(\.\d{3})+(,\d{1,2})?$/.test(s))t=s.replace(/\./g,'').replace(',','.');else if(/^\d+(,\d{1,2})?$/.test(s))t=s.replace(',','.');else if(/^\d+(\.\d{1,2})?$/.test(s))t=s;else throw Error('Informe o valor recebido com até duas casas decimais.');const [a,b='']=t.split('.');const n=Number(a)*100+Number((b+'00').slice(0,2));if(!Number.isSafeInteger(n)||n<1||n>=1e11)throw Error('Valor recebido fora do limite.');return n;}
function toast(text,error=false){clearTimeout(toastTimer);const el=$('#toast');el.textContent=text;el.classList.toggle('error',error);el.hidden=false;toastTimer=setTimeout(()=>el.hidden=true,error?8500:5500);}
function close(){if(dialog.open)dialog.close();content.innerHTML='';}
function open(html){if(dialog.open)dialog.close();content.innerHTML=html;dialog.showModal();setTimeout(()=>{const first=content.querySelector('input:not([type=checkbox]):not([type=radio]),select,textarea');if(first)first.focus({preventScroll:true});},60);}
function errorMessage(err){const text=err?.message||'Não foi possível concluir. Tente novamente.';const target=$('#form-error');if(target){target.textContent=text;target.hidden=false;}toast(text,true);}
function syncCart(){const n=cart.size;$('#cart-count').textContent=String(n);$('.cart-link').setAttribute('aria-label',`Abrir cesta de ajuda: ${n} ${n===1?'causa':'causas'}`);}
function filtered(){let a=DATA.filter(c=>(category==='all'||c.tags.includes(category))&&(region==='all'||(region==='ceara'?c.ceara:!c.ceara))&&(method==='all'||(method==='pix'?pixReady(c):c.methods.includes(method)))&&(!query||norm(c.name+' '+c.ticker+' '+c.title+' '+c.description+' '+c.perspective+' '+c.projects.map(p=>p.t).join(' ')+' '+c.region).includes(norm(query)))&&(view!=='favoritos'||favorites.has(c.id)));
 a.sort((a,b)=>sort==='name'?a.name.localeCompare(b.name,'pt-BR'):sort==='pix'?(Number(pixReady(b))-Number(pixReady(a))||Number(!!b.pix)-Number(!!a.pix)||a.name.localeCompare(b.name,'pt-BR')):(Number(b.ceara)-Number(a.ceara)||DATA.indexOf(a)-DATA.indexOf(b)));return a;}
function categories(){ $('#category-list').innerHTML=cats.map(([id,icon,label])=>`<button class="category ${id===category?'active':''}" data-action="category" data-value="${id}" aria-pressed="${id===category}"><span aria-hidden="true">${icon}</span><span>${label}</span><span class="number">${id==='all'?DATA.length:DATA.filter(c=>c.tags.includes(id)).length}</span></button>`).join('');}

/* ⚡ Pix rápido: escolher a instituição, o valor e gerar o QR sem sair da página. */
const quick={id:(DATA.find(c=>pixReady(c))||DATA.find(c=>c.pix)||{}).id||'',amount:2000};
function renderQuickPix(){const box=$('#quick-pix');if(!box)return;const list=DATA.filter(c=>c.pix),c=cause(quick.id)||list[0];if(!c){box.hidden=true;return;}quick.id=c.id;
 let panel;
 if(pixReady(c)){const payload=C.pix(c.pix,quick.amount);panel=`<div class="qp-pay"><div class="qr-box">${C.qrSvg(payload)}</div><div class="qp-info"><div class="pix-amount">${C.cash(quick.amount)}</div><div class="pix-receiver">${e(c.name)}<small>${e(c.pix.legalName)} · CNPJ ${e(c.pix.cnpj)}</small></div><label class="field-label" for="qp-payload">Pix Copia e Cola</label><textarea id="qp-payload" class="copy-field" readonly spellcheck="false">${e(payload)}</textarea><div class="row"><button class="btn primary" data-action="qp-copy">📋 Copiar código</button><button class="btn orange" data-action="record" data-id="${c.id}" data-value="${quick.amount}">✅ Já doei · registrar e ganhar XP</button></div><p class="small">${fresh(c)?'Chave conferida na fonte oficial em '+day(c.checked)+'.':'Chave conferida por você no site oficial neste navegador.'} Confira no banco o nome do recebedor antes de autorizar. Pague uma vez só.</p></div></div>`;}
 else panel=`<div class="qp-check"><h3>🛡️ Conferência anti-golpe antes do Pix</h3><p>A chave desta ficha foi consultada em ${day(c.checked)}. Para liberar o QR, abra a página oficial e confira se a chave publicada é exatamente esta:</p><p class="key-text"><strong>${e(c.pix.key)}</strong><br><small>${e(c.pix.legalName)} · CNPJ ${e(c.pix.cnpj)}</small></p><p>${ext(c.source,'Abrir a página oficial de doação','btn secondary')}</p><label class="check"><input type="checkbox" id="qp-confirm"><span>Abri o site oficial e a chave é a mesma. Sei que o banco vai mostrar o nome do recebedor e que, se for diferente, não devo pagar.</span></label><button class="btn primary" data-action="qp-check" data-id="${c.id}">Conferi · liberar o QR por 30 dias</button></div>`;
 box.hidden=false;box.innerHTML=`<div class="qp-head"><div><span class="eyebrow">⚡ PIX RÁPIDO · DIRETO À INSTITUIÇÃO</span><h2>Doe em 3 toques.</h2><p class="small">1. Escolha a causa · 2. Escolha o valor · 3. Leia o QR no app do seu banco. Nada passa por este site.</p></div></div><div class="qp-orgs" role="group" aria-label="Instituições com chave Pix publicada">${list.map(x=>`<button class="qp-org ${x.id===c.id?'active':''}" data-action="qp-org" data-id="${x.id}" aria-pressed="${x.id===c.id}"><span aria-hidden="true">${x.icon}</span><b>${e(x.ticker)}</b><small>${e(x.name)}</small><i>${pixReady(x)?'✓ pronto':'🔄 conferir'}</i></button>`).join('')}</div><div class="amount-options qp-amounts">${[1000,2000,5000,10000].map(v=>`<button type="button" class="amount-option ${v===quick.amount?'active':''}" data-action="qp-amount" data-value="${v}">${C.cash(v)}</button>`).join('')}<label class="qp-other">Outro valor <input id="qp-value" inputmode="decimal" maxlength="12" value="${moneyInput(quick.amount)}" aria-label="Outro valor em reais"></label></div>${panel}<p class="small qp-others">Sem chave publicada aqui: ${DATA.filter(x=>!x.pix).map(x=>`<button class="link-like" data-action="cause" data-id="${x.id}">${x.icon} ${e(x.name)}</button>`).join(' · ')} — use o canal oficial de cada uma.</p>`;}
function renderCatalog(){categories();$('#region').value=region;$('#method').value=method;$('#sort').value=sort;const a=filtered();$('#results-count').textContent=`${a.length} ${a.length===1?'iniciativa encontrada':'iniciativas encontradas'}`;$('#catalog-title').textContent=view==='favoritos'?'Causas que você quer guardar por perto.':'Há uma causa esperando seu cuidado.';$('#hero').hidden=view==='favoritos';const qp=$('#quick-pix');if(qp){if(view==='favoritos')qp.hidden=true;else try{renderQuickPix();}catch(err){qp.hidden=true;}}
 $('#cause-grid').innerHTML=a.length?a.map(c=>`<article class="cause-card"><div class="card-art ${e(c.color)}"><span class="location-badge">${c.ceara?'FOCO NO CEARÁ':'CAUSA PARA CONHECER'}</span><button class="favorite" data-action="favorite" data-id="${c.id}" aria-label="${favorites.has(c.id)?'Remover':'Salvar'} ${e(c.name)} nos favoritos" aria-pressed="${favorites.has(c.id)}">${favorites.has(c.id)?'♥':'♡'}</button><span class="art-emoji" aria-hidden="true">${c.icon}</span><span class="art-label">${e(c.ticker)} · ${e(c.art)}</span></div><div class="card-body"><span class="org">${e(c.name)}</span><h3>${e(c.title)}</h3><p class="desc">${e(c.description)}</p><p class="perspective"><b>🔭 Perspectiva:</b> ${e(c.perspective)}</p><ul class="mini-projects">${c.projects.slice(0,3).map(p=>`<li>📌 ${e(p.t)}</li>`).join('')}</ul><div class="card-region"><span aria-hidden="true">⌖</span>${e(c.region)}</div><div class="method-tags"><span class="tag ${pixReady(c)?'':'warm'}">${pixLabel(c)}</span>${c.methods.includes('voluntariado')?'<span class="tag">Voluntariado</span>':''}${c.methods.includes('materiais')?'<span class="tag">Materiais</span>':''}${c.methods.includes('sangue')?'<span class="tag">🩸 Sangue</span>':''}</div><div class="card-buttons"><button class="btn primary" data-action="cause" data-id="${c.id}">Projetos e como ajudar <span aria-hidden="true">→</span></button><button class="add" data-action="add" data-id="${c.id}" aria-label="Adicionar ${e(c.name)} à cesta">${cart.has(c.id)?'✓':'+'}</button></div><span class="source-stamp">${ext(c.source,'Fonte consultada · '+day(c.checked))}</span></div></article>`).join(''):`<div class="empty"><span class="symbol" aria-hidden="true">♡</span><h3>${view==='favoritos'&&!favorites.size?'Sua lista está começando.':'Nenhuma causa com esses filtros.'}</h3><p>${view==='favoritos'&&!favorites.size?'Toque no coração de uma causa para guardá-la neste navegador.':'Experimente outra palavra ou amplie as categorias e regiões.'}</p><button class="btn primary" data-action="reset-filters">${view==='favoritos'?'Explorar todas as causas':'Limpar filtros'}</button></div>`;}
function navigate(route){if(location.hash==='#'+route){renderRoute();return;}location.hash=route;}
function browse(){navigate('explorar');requestAnimationFrame(()=>$('#catalog-heading').scrollIntoView({block:'start'}));}
function renderRoute(){const route=location.hash.slice(1);view=['explorar','favoritos','carteira','cesta','como-funciona','app'].includes(route)?route:'explorar';for(const id of ['catalog-view','wallet-view','selection-view','about-view','app-view'])$('#'+id).hidden=true;
 const active=(view==='explorar'||view==='favoritos')?'catalog-view':view==='carteira'?'wallet-view':view==='cesta'?'selection-view':view==='app'?'app-view':'about-view';$('#'+active).hidden=false;
 document.querySelectorAll('.nav a,.mobile-nav a').forEach(a=>{const selected=a.getAttribute('href')==='#'+view;a.classList.toggle('active',selected);if(selected)a.setAttribute('aria-current','page');else a.removeAttribute('aria-current');});
 if(active==='catalog-view')renderCatalog();if(view==='carteira')renderWallet().catch(errorMessage);if(view==='cesta')renderSelection();if(view==='app')renderCalculator();if(view==='como-funciona')$('#source-list').innerHTML=DATA.map(c=>`<div class="source-entry">${ext(c.source,c.name)}<small>${day(c.checked)} · ${c.pix?'chave Pix publicada':'canal de ajuda'} · projetos: ${ext(c.projSource.url,c.projSource.label)} (${e(c.projSource.type)}, ${day(c.projSource.checked)})</small></div>`).join('');syncCart();}
function checkForm(c,where){return `<div class="qp-check"><h3>🛡️ Conferência anti-golpe</h3><p>A consulta desta chave tem mais de 30 dias (${day(c.checked)}). Abra a página oficial e confira se a chave publicada é exatamente:</p><p class="key-text"><strong>${e(c.pix.key)}</strong><br><small>${e(c.pix.legalName)} · CNPJ ${e(c.pix.cnpj)}</small></p><p>${ext(c.source,'Abrir a página oficial de doação','btn secondary')}</p><label class="check"><input type="checkbox" id="${where}-confirm"><span>Abri o site oficial e a chave é a mesma. Se o banco mostrar outro recebedor, não pago.</span></label><button class="btn primary" type="button" data-action="donor-check" data-id="${c.id}" data-value="${where}">Conferi · liberar o Pix por 30 dias</button></div>`;}
function showCause(id){const c=cause(id);if(!c)return;const amount=cart.get(id)||2500;
 open(`<div class="detail-header"><span class="detail-icon" aria-hidden="true">${c.icon}</span><div><span class="dialog-kicker">${e(c.ticker)} · ${e(c.region)}</span><h2 id="dialog-title">${e(c.name)}</h2></div></div><p class="dialog-text">${e(c.proposal)}</p><div class="perspective-box"><b>🔭 Perspectiva</b><p>${e(c.perspective)}</p><b>📌 Projetos desenvolvidos</b><ul class="project-list">${c.projects.map(p=>`<li><strong>${e(p.t)}</strong> — ${e(p.d)}</li>`).join('')}</ul><p class="small">Fonte (${e(c.projSource.type)}, ${day(c.projSource.checked)}): ${ext(c.projSource.url,c.projSource.label)}. Síntese objetiva; não é auditoria nem promessa de resultado.</p></div><div class="detail-links">${ext(c.website,'Conhecer a instituição')}${ext(c.source,'Conferir a fonte de doação')}</div><div class="data-line"><span>Fonte de doação consultada</span><strong>${day(c.checked)} · não é auditoria</strong></div><div class="data-line"><span>Necessidade e arrecadação atuais</span><strong>Não verificadas neste catálogo</strong></div><div class="data-line"><span>Outras formas de ajudar</span><strong>${e(c.methods.filter(x=>x!=='dinheiro').map(x=>methods[x]).join(' · '))}</strong></div><p class="small">${e(c.extra)}</p>${c.pix&&!pixReady(c)?checkForm(c,'detail'):''}${c.methods.includes('dinheiro')?`<form id="donation-form" data-id="${c.id}" class="stack"><label class="form-field">Valor que você pretende contribuir (R$)<input id="donation-value" name="amount" type="text" inputmode="decimal" value="${moneyInput(amount)}" maxlength="12" required></label><div class="amount-options">${[1000,2500,5000,10000].map(v=>`<button type="button" class="amount-option ${v===amount?'active':''}" data-action="amount" data-value="${v}">${C.cash(v)}</button>`).join('')}</div><p class="small">Valores apenas para sua organização. Você escolhe quanto cabe nas suas possibilidades. As condições dos canais externos podem ser diferentes.</p><div id="form-error" class="error-text" hidden></div><div class="row"><button class="btn orange" type="submit">${pixReady(c)?'⚡ Gerar Pix direto à instituição':'Ver o canal oficial de ajuda'}</button><button class="btn secondary" type="button" data-action="add" data-id="${c.id}">Adicionar à cesta</button></div></form>`:`<div class="row">${ext(c.helpUrl,'Abrir o canal oficial','btn orange')}<button class="btn secondary" type="button" data-action="record" data-id="${c.id}" data-value="0">Já ajudei · registrar e ganhar XP</button></div>`}<p class="small">O site não recebe dinheiro, não conclui transferências e não confirma pagamentos.</p>`);}
function showOfficial(c,amount){open(`<span class="dialog-kicker">PAGAMENTO FORA DESTE SITE</span><h2 id="dialog-title">Continue no canal da instituição.</h2><p class="dialog-text">Você escolheu apoiar <strong>${e(c.name)}</strong>. O valor planejado aqui é <strong>${C.cash(amount)}</strong>, mas ele não é enviado automaticamente ao site externo.</p><div class="info">Informe ou confira o valor, a frequência e a forma de pagamento no canal oficial. Não há chave Pix cadastrada nesta versão, ou a chave ainda precisa da sua conferência anti-golpe.</div>${c.pix?checkForm(c,'official'):''}<div class="dialog-buttons">${ext(c.helpUrl,'Abrir canal oficial','btn primary')}<button class="btn secondary" data-action="record" data-id="${c.id}" data-value="${amount}">Registrar ajuda já realizada</button></div><p class="small">Abrir o link não significa doar. Um registro pessoal também não confirma recebimento.</p>`);}
function showPix(c,amount){if(!pixReady(c)){showOfficial(c,amount);return;}const payload=C.pix(c.pix,amount),svg=C.qrSvg(payload);
 open(`<span class="dialog-kicker">PIX ESTÁTICO · SEM INTERMEDIAÇÃO</span><h2 id="dialog-title">Um gesto direto para a causa.</h2><div class="pix-top"><div class="qr-box">${svg}</div><div><div class="pix-amount">${C.cash(amount)}</div><div class="pix-receiver">${e(c.name)}<small>${e(c.pix.legalName)}</small></div><p class="small">CNPJ da instituição: <b>${e(c.pix.cnpj)}</b></p><p class="key-text">Chave publicada:<br><strong>${e(c.pix.key)}</strong></p>${ext(c.source,'Conferir fonte e recebedor','small')}</div></div><div class="warning"><strong>Antes de autorizar no banco:</strong> confira o recebedor, o documento e o valor. Se houver divergência, não pague. O nome mostrado neste site não substitui a identificação feita pelo banco.</div><label class="field-label" for="pix-payload">Pix Copia e Cola</label><textarea id="pix-payload" class="copy-field" readonly spellcheck="false">${e(payload)}</textarea><div class="dialog-buttons"><button class="btn primary" data-action="copy-pix">Copiar código Pix</button><button class="btn secondary" data-action="download-qr" data-id="${c.id}" data-value="${amount}">Baixar QR Code</button></div><p class="small">Gerar ou copiar este código não faz uma doação. Ele não tem confirmação automática nem expiração bancária definida por este site. Pague apenas uma vez; códigos estáticos podem ser reutilizados. ${fresh(c)?'Fonte: '+day(c.checked)+'.':'Chave conferida por você no site oficial.'}</p><hr><button class="btn orange full" data-action="record" data-id="${c.id}" data-value="${amount}">✅ Já realizei a ajuda · registrar e ganhar XP</button><p class="small">O registro é autodeclarado e não é comprovante bancário ou recibo fiscal.</p>`);}
function renderSelection(){const values=[...cart.entries()],total=values.reduce((s,[,v])=>s+v,0);$('#selection-content').innerHTML=!values.length?`<div class="empty"><span class="symbol">♡</span><h3>Sua cesta ainda está vazia.</h3><p>Adicione causas para planejar sua ajuda. Nada é cobrado ao montar a cesta.</p><a href="#explorar" class="btn primary">Explorar causas →</a></div>`:`<div class="selection-layout"><div>${values.map(([id,amount])=>{const c=cause(id);return `<article class="selection-item"><span class="selection-icon" aria-hidden="true">${c.icon}</span><div><h3>${e(c.name)}</h3><p>${e(c.region)}</p><div class="row"><button class="btn primary" data-action="pay-cart" data-id="${id}">${pixReady(c)?'Gerar Pix':'Canal oficial'}</button><button class="btn secondary" data-action="record" data-id="${id}" data-value="${amount}">Registrar ajuda</button></div></div><div class="selection-value"><label>Planejado (R$) <input class="amount-input cart-amount" data-id="${id}" value="${moneyInput(amount)}" inputmode="decimal" maxlength="12" aria-label="Valor planejado para ${e(c.name)}"></label><button class="remove-item" data-action="remove-cart" data-id="${id}">Remover da cesta</button></div></article>`;}).join('')}</div><aside class="panel"><span class="eyebrow">APENAS PLANEJAMENTO</span><h2>Sua intenção de ajudar</h2><p>${values.length} ${values.length===1?'causa selecionada':'causas selecionadas'}</p><div class="selection-total">${C.cash(total)}</div><div class="info">Não há pagamento único, saldo ou rateio. Cada ajuda é feita separadamente, diretamente ao destinatário.</div><p class="small">Esta cesta fica salva neste navegador, quando o armazenamento local é permitido. Valores nela não entram no total de doações informadas da carteira.</p><a href="#carteira" class="btn secondary full">Abrir minha carteira</a></aside></div>`;}
function resumeRecord(){if(pendingRecord){const p=pendingRecord;pendingRecord=null;showRecord(p.id,p.amount);}}

/* ⭐ Avaliação do XP da Boa Ação — mesma régua do Placar XP (planilha). */
function evalFields(prefix,ev,kind){const x=ev||{necessidade:2,gratidao:2,oportunidade:2,criatividade:1,seguranca:X.suggestSecurity(true,false),reserva:true,recebidoCents:null};
 return `<fieldset class="xp-eval" id="${prefix}-xp"><legend>⭐ XP da Boa Ação · avalie com honestidade</legend><p class="small">XP é honra e mérito, não dinheiro: o valor só entra pela proporção do que você recebeu, e doar além da medida não rende mais XP.</p>${X.CRITERIA.map(c=>`<div class="crit"><span class="crit-label">${c.icon} <b>${c.label}</b><small>${e(c.hint)}</small></span><span class="seg" role="radiogroup" aria-label="${c.label}">${[0,1,2,3].map(v=>`<label title="${e(c.scale[v])}"><input type="radio" name="${c.id}" value="${v}" ${x[c.id]===v?'checked':''}><span>${v}</span></label>`).join('')}</span><small class="crit-scale" data-scale="${c.id}">${e(c.scale[x[c.id]])}</small></div>`).join('')}<div class="crit"><span class="crit-label">🏦 <b>Reserva preservada?</b><small>Seu sustento e sua reserva continuam protegidos?</small></span><span class="seg"><label><input type="radio" name="reserva" value="sim" ${x.reserva?'checked':''}><span>Sim</span></label><label><input type="radio" name="reserva" value="nao" ${x.reserva?'':'checked'}><span>Não</span></label></span><small class="crit-scale">${x.reserva?'Ajuda dentro das possibilidades':'Trava: quem se prejudica não pontua'}</small></div><label class="form-field xp-received" ${kind&&kind!=='dinheiro'?'hidden':''}>Recebido no período (R$, opcional) <span class="small">Renda do mês ou período da doação. Fica só no seu cofre e calcula a medida (ideal: 5%). Em branco, a medida conta como 1.</span><input type="text" inputmode="decimal" name="recebido" maxlength="16" value="${x.recebidoCents?moneyInput(x.recebidoCents):''}" placeholder="opcional"></label><output class="xp-preview" id="${prefix}-preview" aria-live="polite"></output></fieldset>`;}
function readEval(form){const d=new FormData(form),x={};for(const c of X.CRITERIA){const v=Number(d.get(c.id));if(!Number.isInteger(v)||v<0||v>3)throw Error('Avalie todos os critérios do XP (0 a 3).');x[c.id]=v;}x.reserva=d.get('reserva')!=='nao';const kindField=form.querySelector('[name=kind]');const kind=kindField?kindField.value:form.dataset.kind||'dinheiro';x.recebidoCents=kind==='dinheiro'?bigCents(d.get('recebido')):null;return x;}
function previewXp(form){const out=form.querySelector('.xp-preview');if(!out)return;try{const x=readEval(form);const kindField=form.querySelector('[name=kind]');const kind=kindField?kindField.value:form.dataset.kind||'dinheiro';let amountCents=0;const am=form.querySelector('[name=amount]');if(kind==='dinheiro'&&am)try{amountCents=C.cents(am.value);}catch{amountCents=0;}if(form.dataset.amount)amountCents=Number(form.dataset.amount);const s=X.score({kind,amountCents,xp:x});
 for(const el of form.querySelectorAll('[data-scale]')){const c=X.CRITERIA.find(k=>k.id===el.dataset.scale);el.textContent=c.scale[x[c.id]];}
 out.innerHTML=s.lock?`<b>XP previsto: 0</b> · trava de ${s.lock==='reserva'?'reserva comprometida':'destinatário não verificado'}`:`<b>XP previsto: ${X.fmt(s.xp)}</b> · qualidade ${s.quality.toFixed(2).replace('.',',')} · medida ${s.measure.toFixed(2).replace('.',',')}${s.proportion!==null?' · proporção '+(s.proportion*100).toFixed(1).replace('.',',')+'%':''}`;}catch(err){out.textContent=err.message;}}
async function renderWallet(){const renderId=++walletRenderId;const target=$('#wallet-content');
 if(VITRINE){target.innerHTML=`<div class="lock-layout"><article class="panel lock-panel"><span class="lock-symbol" aria-hidden="true">📲</span><span class="beta-label">VITRINE PÚBLICA · SEM COFRE NESTE ENDEREÇO</span><h2>Sua carteira e seu XP moram no app.</h2><p>Por segurança, este endereço é compartilhado com outros sites e não guarda carteiras. Baixe o app <b>Bolsa Ajuda de Boa</b> (um arquivo único, offline) ou use a edição com carteira no endereço exclusivo.</p><div class="stack"><a class="btn primary full" href="#app">⬇️ Baixar o app Bolsa Ajuda de Boa</a><a class="btn secondary full" href="https://shop-ajuda-de-boa.aldenirmed.chatgpt.site/#carteira" target="_blank" rel="noopener noreferrer">Abrir a carteira no endereço exclusivo ↗</a></div></article><aside class="panel status-panel"><h2>Mesmo cofre, mesmo XP.</h2><p>O app e a edição com carteira usam o mesmo formato de backup criptografado (AES-256-GCM) e a mesma régua do XP da Boa Ação. Exporte num, importe no outro.</p><hr><h3>Privacidade</h3><p>Nada é enviado a servidor. A senha nunca sai do seu aparelho. Não existe ranking público: seu XP é só seu.</p></aside></div>`;return;}
 if(V.locked){target.innerHTML='<div class="panel"><p>Verificando armazenamento local…</p></div>';try{hasVault=await V.exists();}catch(err){if(renderId!==walletRenderId)return;target.innerHTML=`<div class="panel"><h2>O catálogo está disponível, mas a carteira não abriu.</h2><p>${e(err.message)}</p><p>Use um navegador atualizado, em HTTPS ou no endereço local indicado no arquivo LEIA-ME. Nenhum dado da carteira foi salvo. Alternativa: <a href="#app">baixe o app Bolsa Ajuda de Boa</a>.</p></div>`;return;}if(renderId!==walletRenderId)return;
 target.innerHTML=`${pendingRecord?'<div class="info">Abra sua carteira para continuar o registro. Nenhuma doação foi confirmada e nenhum registro foi salvo ainda.</div><br>':''}<div class="lock-layout"><article class="panel lock-panel"><span class="lock-symbol" aria-hidden="true">▣</span><span class="beta-label">LOCAL · NÃO É UMA CONTA ONLINE</span><h2>${hasVault?'Bem-vindo à sua carteira.':'Sua ajuda merece uma memória.'}</h2><p>${hasVault?'Use a senha local que você criou neste navegador. Não use senhas de banco.':'Crie um cofre local para seus registros, comprovantes e seu XP da Boa Ação. Não pedimos nome, CPF, e-mail ou dados de cartão.'}</p><form id="${hasVault?'unlock-form':'create-form'}" class="stack"><label class="form-field">Senha exclusiva da carteira<input type="password" name="password" minlength="12" maxlength="256" autocomplete="${hasVault?'current-password':'new-password'}" placeholder="Uma frase longa que só você conhece" required></label>${hasVault?'':`<label class="form-field">Repita a senha<input type="password" name="confirmation" minlength="12" maxlength="256" autocomplete="new-password" required></label><label class="check"><input type="checkbox" name="consent" required><span>Entendi que a senha não pode ser recuperada e que preciso exportar um backup para não depender apenas deste navegador.</span></label>`}<div id="form-error" class="error-text" hidden></div><button class="btn primary full" type="submit">${hasVault?'Abrir carteira local':'Criar minha carteira local'}</button></form><button class="btn subtle full" data-action="import" style="margin-top:13px">Importar backup criptografado</button>${hasVault?'<button class="btn subtle full" data-action="reset-vault" style="margin-top:10px">Apagar carteira deste navegador</button>':''}</article><aside class="panel status-panel"><h2>Privada no seu dispositivo.</h2><p>Registros, anexos e avaliações de XP ficam criptografados neste navegador. A senha não é enviada a um servidor, e não existe painel público de doadores.</p><hr><h3>O que você poderá acompanhar</h3><p>Valores informados, instituições apoiadas, data e tipo da ajuda, documentos anexados, distribuição por causa e seu XP da Boa Ação com nível e conquistas.</p><hr><div class="warning"><b>Não é comprovante de pagamento.</b><br>O aplicativo não valida comprovantes nem recebe confirmação bancária. Seu banco e a instituição são as fontes dessa confirmação.</div><hr><h3>Guarde sua chave de acesso.</h3><p>Use uma frase longa, exclusiva e memorável. Exporte o backup criptografado — ele abre também no app Bolsa Ajuda de Boa. Limpar o navegador pode apagar sua carteira.</p><p class="small">Criptografia local não protege um dispositivo já comprometido. Não houve auditoria externa desta aplicação. Antes de usar comprovantes pessoais, teste criar, bloquear, reabrir e restaurar uma carteira de teste em HTTPS.</p></aside></div>`;return;}
 const entries=V.data.entries,months=[...new Set(entries.map(r=>r.date.slice(0,7)))].sort().reverse();if(period!=='all'&&!months.includes(period))period='all';const rows=entries.filter(r=>period==='all'||r.date.startsWith(period));const monetary=rows.filter(r=>r.kind==='dinheiro');const total=monetary.reduce((s,r)=>s+r.amountCents,0),unique=new Set(rows.map(r=>r.causeId)).size,proofs=rows.filter(r=>r.evidence).length;
 const distribution=new Map();for(const r of monetary){const cat=cause(r.causeId).category;distribution.set(cat,(distribution.get(cat)||0)+r.amountCents);}
 const xs=X.summary(entries,cause),xp=X.summary(rows,cause);
 target.innerHTML=`<div class="wallet-tools"><button class="btn primary" data-action="record">+ Registrar uma ajuda</button><button class="btn secondary" data-action="backup">Exportar backup</button><button class="btn secondary" data-action="csv">Exportar CSV · todos</button><button class="btn secondary" data-action="placar-csv">⭐ Placar XP (CSV da planilha)</button><button class="btn subtle spacer" data-action="lock">Bloquear carteira</button></div><section class="xp-panel" aria-label="XP da Boa Ação"><div class="xp-level"><span class="xp-icon" aria-hidden="true">${xs.level.icon}</span><div><span class="eyebrow">SEU XP DA BOA AÇÃO · PRIVADO</span><h2>${e(xs.level.name)}</h2><p class="xp-total"><b>${X.fmt(xs.total)}</b> XP acumulado</p><div class="xp-bar" role="img" aria-label="Progresso até ${e(xs.level.next)}"><span style="width:${(xs.level.progress*100).toFixed(1)}%"></span></div><small>Faltam ${X.fmt(xs.level.toNext)} XP para <b>${e(xs.level.next)}</b>. O XP tende ao infinito.</small></div></div><div class="xp-numbers"><div><small>No período</small><b>${X.fmt(xp.total)}</b></div><div><small>Média por ajuda</small><b>${X.fmt(xs.mean)}</b></div><div><small>Desvio padrão</small><b>${X.fmt(xs.sd)}</b></div><div><small>Avaliadas</small><b>${xs.evaluated}/${xs.count}</b></div><div><small>Travas</small><b>${xs.locks}</b></div></div><div class="badges">${xs.badges.map(b=>`<span class="badge ${b.ok?'on':''}" title="${e(b.hint)}">${b.icon} ${e(b.name)}</span>`).join('')}</div>${xs.pending?`<p class="small">⏳ ${xs.pending} ${xs.pending===1?'ajuda ainda não foi avaliada':'ajudas ainda não foram avaliadas'} — use “Avaliar XP” no histórico.</p>`:''}</section><div class="warning" style="margin-bottom:20px"><strong>Todos os valores são informados por você.</strong> Anexos não foram autenticados. Não há confirmação bancária, saldo disponível ou dinheiro guardado nesta plataforma. O XP é uma régua pessoal de honra, sem valor monetário.</div><div class="row" style="margin-bottom:18px"><label class="form-field">Período dos indicadores<select id="wallet-period"><option value="all">Todo o histórico</option>${months.map(m=>`<option value="${m}" ${period===m?'selected':''}>${m.slice(5)}/${m.slice(0,4)}</option>`).join('')}</select></label><span class="small">Os arquivos de backup e CSV incluem todo o histórico.</span></div><div class="stats"><div class="stat"><small>Doações informadas</small><b>${C.cash(total)}</b><span>Sem validação bancária</span></div><div class="stat"><small>Registros no período</small><b>${rows.length}</b><span>Dinheiro, materiais, tempo, sangue e divulgação</span></div><div class="stat"><small>Instituições apoiadas</small><b>${unique}</b><span>Segundo seus registros</span></div><div class="stat"><small>Documentos anexados</small><b>${proofs}</b><span>Arquivos não autenticados</span></div></div><div class="wallet-grid"><article class="panel"><h2>Seu histórico de ajuda</h2><div class="record-list">${rows.length?rows.map(recordHtml).join(''):`<div class="empty"><span class="symbol">♡</span><h3>Um começo com espaço para o bem.</h3><p>Depois de ajudar por um canal oficial, registre aqui. A carteira começa vazia: nenhum pagamento foi simulado.</p><button class="btn primary" data-action="record">Registrar minha primeira ajuda</button></div>`}</div></article><aside class="panel"><span class="eyebrow">PARA ONDE VOCÊ DIRECIONOU</span><h2>Suas causas</h2><p class="small">Distribuição dos valores autodeclarados no período. Não mede impacto real nem recebimento.</p>${total?[...distribution.entries()].sort((a,b)=>b[1]-a[1]).map(([cat,n])=>`<div class="distribution"><div class="distribution-head"><span>${e(cats.find(x=>x[0]===cat)?.[2]||cat)}</span><b>${C.cash(n)}</b></div><div class="bar" role="img" aria-label="${e(cat)}: ${C.cash(n)}"><span style="width:${(n/total*100).toFixed(2)}%"></span></div></div>`).join(''):'<p class="small">A distribuição aparece após um registro financeiro.</p>'}<hr><h3>Dinheiro não é a única forma.</h3><p class="small">${rows.filter(r=>r.kind!=='dinheiro').length} registros de tempo, materiais, sangue ou divulgação no período. Eles não recebem uma conversão inventada para reais — e pontuam XP pela qualidade do gesto.</p><hr><h3>Um cuidado com a sua memória</h3><p class="small">Exporte o backup regularmente e guarde a senha separadamente. Não publique o backup nem os documentos no GitHub.</p><button class="btn subtle full" data-action="backup">Baixar backup criptografado</button><a class="btn subtle full" href="#app" style="margin-top:10px">📲 Abrir no app Bolsa Ajuda de Boa</a></aside></div>`;}
function recordHtml(r){const c=cause(r.causeId),s=X.score(r);return `<article class="record"><div><h3>${c.icon} ${e(c.name)}</h3><p>${day(r.date)} · ${kindLabel[r.kind]||r.kind}</p>${r.detail?`<p>${e(r.detail)}</p>`:''}<span class="record-status">${r.evidence?'Arquivo anexado · não validado':'Autodeclarada · não confirmada'}</span> <span class="xp-chip ${s.evaluated?(s.lock?'lock':''):'pending'}">${s.evaluated?(s.lock?'🔒 0 XP · trava':'⭐ +'+X.fmt(s.xp)+' XP'):'⏳ XP pendente'}</span></div><div class="value">${r.kind==='dinheiro'?C.cash(r.amountCents):'Ajuda não financeira'}</div><div class="record-actions"><button data-action="evaluate" data-id="${r.id}">${s.evaluated?'Revisar XP':'Avaliar XP'}</button><button data-action="receipt" data-id="${r.id}">Ver registro pessoal</button>${r.evidence?`<button data-action="evidence" data-id="${r.id}">Baixar anexo original</button>`:''}<button class="delete" data-action="delete-record" data-id="${r.id}">Excluir registro</button></div></article>`;}
function showRecord(id='',amount=2500){if(VITRINE){close();navigate('app');toast('Para registrar e somar XP, use o app Bolsa Ajuda de Boa ou a edição com carteira.');return;}if(V.locked){pendingRecord={id,amount};close();navigate('carteira');return;}const value=cause(id)?id:'';const c=cause(value);const defKind=c&&!c.methods.includes('dinheiro')&&c.methods.includes('sangue')?'sangue':'dinheiro';open(`<span class="dialog-kicker">REGISTRO PESSOAL · SOMENTE NESTE NAVEGADOR</span><h2 id="dialog-title">Uma ajuda para não esquecer.</h2><p class="dialog-text">Registre somente uma ajuda que você já realizou. Este formulário não executa nem comprova pagamento.</p><form id="record-form" class="stack"><label class="form-field">Instituição<select name="causeId" required><option value="">Selecione uma instituição</option>${DATA.map(c=>`<option value="${c.id}" ${c.id===value?'selected':''}>${e(c.ticker)} · ${e(c.name)}</option>`).join('')}</select></label><div class="form-row"><label class="form-field">Data informada<input type="date" name="date" value="${today()}" max="${today()}" min="1900-01-01" required></label><label class="form-field">Tipo de ajuda<select name="kind" id="record-kind">${Object.entries(kindLabel).map(([k,l])=>`<option value="${k}" ${k===defKind?'selected':''}>${l}</option>`).join('')}</select></label></div><label class="form-field" id="record-amount-field" ${defKind==='dinheiro'?'':'hidden'}>Valor efetivamente informado (R$)<input type="text" inputmode="decimal" name="amount" maxlength="12" value="${moneyInput(amount||2500)}" ${defKind==='dinheiro'?'required':''}></label><label class="form-field">Descrição breve <span class="small">Obrigatória para materiais, tempo e divulgação. Não inclua nome de beneficiários, CPF ou informações de saúde.</span><textarea name="detail" maxlength="240" rows="2" placeholder="Ex.: participação em ação voluntária ou materiais entregues"></textarea></label><label class="form-field">Anexar seu comprovante verdadeiro (opcional)<input type="file" name="evidence" accept="application/pdf,image/png,image/jpeg,image/webp"><span class="small">PDF, PNG, JPG ou WebP, até 3 MB. O arquivo original fica no cofre local; não é enviado nem anonimizado. Anexar sobe a Segurança do XP.</span></label>${evalFields('record',null,defKind)}<label class="check"><input type="checkbox" name="declare" required><span>Entendi que esta ajuda é autodeclarada. O registro não prova recebimento, não autentica o anexo e não é recibo bancário ou fiscal.</span></label><div id="form-error" class="error-text" hidden></div><button class="btn primary full" type="submit">Salvar registro no meu cofre local</button></form>`);previewXp($('#record-form'));}
function showEvaluate(id){const r=entry(id);if(!r)throw Error('Abra sua carteira.');const c=cause(r.causeId);open(`<span class="dialog-kicker">XP DA BOA AÇÃO · ${e(c.ticker)}</span><h2 id="dialog-title">${r.xp?'Revisar':'Avaliar'} a ajuda de ${day(r.date)}.</h2><p class="dialog-text">${c.icon} ${e(c.name)} · ${kindLabel[r.kind]}${r.kind==='dinheiro'?' · '+C.cash(r.amountCents):''}</p><form id="eval-form" class="stack" data-id="${r.id}" data-kind="${r.kind}" data-amount="${r.amountCents}">${evalFields('eval',r.xp||{necessidade:2,gratidao:2,oportunidade:2,criatividade:1,seguranca:X.suggestSecurity(true,!!r.evidence),reserva:true,recebidoCents:null},r.kind)}<div id="form-error" class="error-text" hidden></div><button class="btn primary full" type="submit">Salvar avaliação no cofre</button></form>`);previewXp($('#eval-form'));}
function entry(id){return V.data?.entries.find(r=>r.id===id);}
function receiptMarkup(r){const c=cause(r.causeId),s=X.score(r);return `<div class="print-kicker">AJUDA DE BOA · BOLSA AJUDA DE BOA · ORGANIZAÇÃO PESSOAL</div><h1>Registro de ajuda</h1><div class="non-bank">AUTODECLARADO · NÃO É COMPROVANTE BANCÁRIO<br>NÃO É RECIBO FISCAL NEM DOCUMENTO EMITIDO PELA INSTITUIÇÃO</div><div class="receipt-row"><span>Identificação no registro</span><strong>Doador</strong></div><div class="receipt-row"><span>Instituição informada</span><strong>${e(c.name)} (${e(c.ticker)})</strong></div><div class="receipt-row"><span>Data informada pelo doador</span><strong>${day(r.date)}</strong></div><div class="receipt-row"><span>Tipo de ajuda</span><strong>${kindLabel[r.kind]||r.kind}</strong></div>${r.kind==='dinheiro'?`<div class="receipt-row"><span>Valor declarado</span><strong>${C.cash(r.amountCents)}</strong></div>`:''}${r.detail?`<div class="receipt-row"><span>Descrição informada</span><strong>${e(r.detail)}</strong></div>`:''}<div class="receipt-row"><span>XP da Boa Ação (régua pessoal)</span><strong>${s.evaluated?X.fmt(s.xp)+' XP':'Pendente de avaliação'}</strong></div><div class="receipt-row"><span>Condição deste registro</span><strong>${r.evidence?'Arquivo anexado, não autenticado':'Sem anexo; informação do doador'}</strong></div><div class="receipt-row"><span>ID local (não bancário)</span><strong>${e(r.id)}</strong></div><p class="print-foot">Este documento apenas organiza informações inseridas pelo doador. Não confirma pagamento, liquidação, autenticidade de documentos ou recebimento pela instituição. Não existe assinatura ou validação da organização beneficiária. Solicite o comprovante ao banco e eventual recibo diretamente à instituição. O XP é uma pontuação pessoal de honra, sem valor monetário ou fiscal.</p><p class="print-foot">O nome “Doador” neste registro não anonimiza o pagamento perante o banco ou o destinatário. Este arquivo não inclui o comprovante original anexado.</p>`;}
function showReceipt(id){const r=entry(id);if(!r)throw Error('Abra a carteira para acessar este registro.');open(`<span class="dialog-kicker">SALVO LOCALMENTE · NÃO VALIDADO PELO BANCO</span><h2 id="dialog-title">Sua ajuda, registrada.</h2><div class="receipt-preview">${receiptMarkup(r)}</div><div class="dialog-buttons"><button class="btn primary" data-action="print-receipt" data-id="${id}">Imprimir / salvar PDF</button><button class="btn secondary" data-action="download-receipt" data-id="${id}">Baixar registro HTML</button><button class="btn subtle" data-action="go-wallet">Voltar à carteira</button></div>`);}
function download(content,type,name){const blob=content instanceof Blob?content:new Blob([content],{type});const url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=name;a.rel='noopener';document.body.appendChild(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),30000);}
async function copyText(text,fieldId='pix-payload'){if(navigator.clipboard?.writeText){try{await navigator.clipboard.writeText(text);toast('Código copiado. Confira o recebedor e o valor no seu banco.');return;}catch{}}
 const t=document.getElementById(fieldId);if(t){t.focus();t.select();const ok=document.execCommand('copy');toast(ok?'Código copiado. Confira o recebedor no banco.':'Selecione o código e use a opção Copiar do navegador.',!ok);}else throw Error('Use a opção Copiar do seu navegador.');}
async function attachment(file){if(!file||!file.size)return null;if(file.size>V.MAX_FILE)throw Error('O anexo deve ter no máximo 3 MB.');const bytes=new Uint8Array(await file.arrayBuffer()),type=V.signature(bytes);if(!type)throw Error('Use um arquivo PDF, PNG, JPG ou WebP válido. SVG, HTML e outros formatos não são aceitos.');const digest=await crypto.subtle.digest('SHA-256',bytes),hash=[...new Uint8Array(digest)].map(b=>b.toString(16).padStart(2,'0')).join('');if(V.data.entries.some(r=>r.evidence?.sha256===hash))throw Error('Este arquivo já está anexado a outro registro. Confira para evitar contar a mesma ajuda duas vezes.');return{type,bytes:bytes.length,data:C.b64(bytes),sha256:hash};}
function lock(){if(V.locked)return;V.lock();pendingRecord=null;close();$('#print-area').innerHTML='';if(view==='carteira')renderWallet().catch(errorMessage);toast('Carteira bloqueada. Os registros continuam criptografados neste navegador.');}
function suggest(){open(`<span class="dialog-kicker">AMPLIAR A REDE COM RESPONSABILIDADE</span><h2 id="dialog-title">Indique uma instituição.</h2><p class="dialog-text">Esta versão gera uma ficha para revisão manual. Ela <b>não envia nem publica</b> a indicação. Não inclua dados de pessoas atendidas ou chaves Pix.</p><form id="suggest-form" class="stack"><label class="form-field">Nome público da instituição<input name="name" maxlength="100" required></label><label class="form-field">Site oficial (HTTPS)<input name="url" type="url" placeholder="https://" maxlength="300" required></label><div class="form-row"><label class="form-field">Cidade / região de atuação<input name="region" maxlength="100" required></label><label class="form-field">Categoria<select name="category">${cats.filter(c=>c[0]!=='all').map(c=>`<option value="${c[0]}">${c[2]}</option>`).join('')}</select></label></div><label class="form-field">Proposta de ajuda, sem dados pessoais<textarea name="proposal" maxlength="350" required></textarea></label><div id="form-error" class="error-text" hidden></div><button class="btn primary full" type="submit">Baixar ficha de indicação</button></form>`);}
function renderCalculator(){const box=$('#xp-calculator');if(!box||box.dataset.ready)return;box.dataset.ready='1';box.innerHTML=`<form id="calc-form" class="stack"><div class="form-row"><label class="form-field">Tipo de ajuda<select name="kind">${Object.entries(kindLabel).map(([k,l])=>`<option value="${k}">${l}</option>`).join('')}</select></label><label class="form-field">Valor doado (R$, se financeira)<input type="text" inputmode="decimal" name="amount" maxlength="12" value="50,00"></label></div>${evalFields('calc',null,'dinheiro')}</form>`;previewXp($('#calc-form'));}
function csvCell(v){let s=String(v??'');if(/^[\s]*[=+@-]/.test(s))s="'"+s;return '"'+s.replace(/"/g,'""')+'"';}
async function confirmDialog(text){return confirm(text);}
async function action(name,b){const id=b.dataset.id;
 switch(name){
 case'close':close();break;
 case'browse':browse();break;
 case'ceara':region='ceara';category='all';query='';$('#search').value='';browse();renderCatalog();break;
 case'category':category=b.dataset.value;renderCatalog();break;
 case'method':method=b.dataset.value;browse();renderCatalog();break;
 case'reset-filters':category='all';query='';region='all';method='all';$('#search').value='';if(view==='favoritos')navigate('explorar');else renderCatalog();break;
 case'favorite':{if(favorites.has(id))favorites.delete(id);else favorites.add(id);const saved=await savePlan();renderCatalog();if(saved)toast(favorites.has(id)?'Causa salva nos favoritos deste navegador.':'Causa removida dos favoritos.');}break;
 case'cause':showCause(id);break;
 case'add':if(!cause(id))return;{const inDialog=$('#donation-value');const n=inDialog?C.cents(inDialog.value):cart.get(id)||2500;cart.set(id,n);const saved=await savePlan();syncCart();if(view==='cesta')renderSelection();else if(['explorar','favoritos'].includes(view))renderCatalog();if(saved)toast('Causa adicionada à cesta de planejamento. Nenhum pagamento foi feito.');}break;
 case'amount':$('#donation-value').value=moneyInput(Number(b.dataset.value));document.querySelectorAll('#donation-form .amount-option').forEach(x=>x.classList.toggle('active',x===b));break;
 case'qp-org':quick.id=id;renderQuickPix();break;
 case'qp-amount':quick.amount=Number(b.dataset.value);renderQuickPix();break;
 case'qp-copy':await copyText($('#qp-payload').value,'qp-payload');break;
 case'qp-check':case'donor-check':{const c=cause(id);if(!c?.pix)return;const box=name==='qp-check'?$('#qp-confirm'):document.getElementById(b.dataset.value+'-confirm');if(!box?.checked)throw Error('Marque a confirmação depois de conferir a chave no site oficial.');saveDonorCheck(c);toast('Conferência registrada neste navegador por 30 dias. Confira também o recebedor no banco.');if(name==='qp-check'){quick.id=c.id;renderCatalog();}else showCause(c.id);}break;
 case'remove-cart':cart.delete(id);await savePlan();syncCart();renderSelection();break;
 case'pay-cart':{const c=cause(id);if(c)showPix(c,cart.get(id)||2500);}break;
 case'copy-pix':await copyText($('#pix-payload').value);break;
 case'download-qr':{const c=cause(id);if(!pixReady(c))throw Error('Consulte os dados atuais no site oficial.');download(C.qrSvg(C.pix(c.pix,Number(b.dataset.value))),'image/svg+xml',`pix-${id}.svg`);toast('QR Code preparado. Ele não comprova pagamento.');}break;
 case'record':showRecord(id||'',Number(b.dataset.value)||2500);break;
 case'evaluate':showEvaluate(id);break;
 case'receipt':showReceipt(id);break;
 case'go-wallet':close();navigate('carteira');break;
 case'print-receipt':{const r=entry(id);if(!r)throw Error('Abra sua carteira.');const html=receiptMarkup(r);close();$('#print-area').innerHTML=html;window.print();}break;
 case'download-receipt':{const r=entry(id);if(!r)throw Error('Abra sua carteira.');const css='body{font:15px/1.7 Georgia,serif;color:#183b35;max-width:780px;margin:40px auto;padding:20px}h1{font-size:32px}.non-bank{border:2px solid #a44726;color:#913717;font-weight:bold;padding:18px;margin:25px 0}.receipt-row{display:flex;justify-content:space-between;gap:20px;border-bottom:1px solid #ddd;padding:12px 0;font-size:14px}.receipt-row strong{max-width:60%;text-align:right;overflow-wrap:anywhere}.print-kicker,.print-foot{font-size:12px}.print-foot{margin-top:25px}@media print{@page{size:A4;margin:20mm}body{margin:0;padding:0}}';download('<!doctype html><html lang="pt-BR"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta http-equiv="Content-Security-Policy" content="default-src \'none\'; style-src \'unsafe-inline\'; base-uri \'none\'; form-action \'none\'"><title>Registro autodeclarado — não bancário</title><style>'+css+'</style><body>'+receiptMarkup(r)+'</body></html>','text/html',`registro-autodeclarado-${r.date}-${r.id.slice(-6)}.html`);toast('Registro não bancário preparado para download.');}break;
 case'evidence':{const r=entry(id);if(!r?.evidence)throw Error('Anexo não encontrado.');if(!await confirmDialog('O anexo original pode conter dados pessoais e bancários. Ele será baixado sem criptografia e sem anonimização. Continuar?'))return;const extn=({'application/pdf':'pdf','image/jpeg':'jpg','image/png':'png','image/webp':'webp'})[r.evidence.type];download(new Blob([C.unb64(r.evidence.data)],{type:r.evidence.type}),r.evidence.type,`comprovante-original-${r.id.slice(-6)}.${extn}`);}break;
 case'delete-record':if(!await confirmDialog('Excluir este registro e seu anexo da carteira local? A exclusão não estorna uma doação. Backups anteriores continuarão contendo o registro.'))return;await V.mutate(s=>{s.entries=s.entries.filter(r=>r.id!==id);});await renderWallet();toast('Registro excluído da carteira local.');break;
 case'lock':lock();break;
 case'backup':download(await V.backup(),'application/json',`bolsa360-backup-criptografado-${today()}.json`);toast('Backup criptografado preparado. Ele abre também no app Bolsa Ajuda de Boa. Guarde a senha separadamente.');break;
 case'csv':{if(V.locked)throw Error('Abra a carteira antes de exportar.');if(!await confirmDialog('O CSV contém os valores e descrições de todo o histórico sem criptografia. Não inclui anexos. Deseja baixar?'))return;const rows=[['id_local','instituicao','ticker','data_informada','tipo','valor_reais_informado','xp_boa_acao','situacao','descricao'],...V.data.entries.map(r=>{const s=X.score(r);return [r.id,cause(r.causeId).name,cause(r.causeId).ticker,r.date,r.kind,r.kind==='dinheiro'?(r.amountCents/100).toFixed(2).replace('.',','):'',s.evaluated?s.xp.toFixed(2).replace('.',','):'','AUTODECLARADO_NAO_CONFIRMADO',r.detail];})];download('﻿'+rows.map(r=>r.map(csvCell).join(';')).join('\r\n'),'text/csv;charset=utf-8',`bolsa360-historico-autodeclarado-${today()}.csv`);}break;
 case'placar-csv':{if(V.locked)throw Error('Abra a carteira antes de exportar.');if(!await confirmDialog('O CSV do Placar XP contém valores doados e, se informados, valores recebidos, sem criptografia. Ele segue as colunas da aba “Ajudas” da planilha Placar XP da Boa Ação. Baixar?'))return;const rows=X.placarRows(V.data.entries,cause);download('﻿'+rows.map(r=>r.map(csvCell).join(';')).join('\r\n'),'text/csv;charset=utf-8',`placar-xp-boa-acao-${today()}.csv`);toast('Placar XP preparado: cole na aba “Ajudas” da planilha para somar ao XP vigente.');}break;
 case'import':if(!V.locked)throw Error('Bloqueie a carteira antes de importar um backup.');$('#import-file').value='';$('#import-file').click();break;
 case'reset-vault':{const answer=prompt('Isto apaga os registros e anexos deste navegador. Não altera os backups externos nem estorna doações. Digite APAGAR para confirmar.');if(answer!=='APAGAR')return;await V.erase();pendingRecord=null;await renderWallet();toast('Carteira local apagada. Nenhuma conta externa foi alterada.');}break;
 case'suggest':suggest();break;
 }
}
document.addEventListener('click',async ev=>{const b=ev.target.closest('[data-action]');if(!b||b.disabled)return;ev.preventDefault();const previous=b.disabled;b.disabled=true;try{await action(b.dataset.action,b);}catch(err){errorMessage(err);}finally{if(b.isConnected)b.disabled=previous;}});
document.addEventListener('submit',async ev=>{const form=ev.target;ev.preventDefault();if(form.id==='calc-form')return;if(!form.checkValidity()){form.reportValidity();return;}const submit=form.querySelector('[type=submit]');if(submit?.disabled)return;if(submit)submit.disabled=true;const d=new FormData(form);try{
 switch(form.id){
 case'search-form':query=String(d.get('search')||$('#search').value).trim();navigate('explorar');renderCatalog();$('#catalog-heading').scrollIntoView({block:'start'});break;
 case'donation-form':{const c=cause(form.dataset.id),n=C.cents(d.get('amount'));if(c)showPix(c,n);}break;
 case'create-form':{const password=String(d.get('password'));if(password!==String(d.get('confirmation')))throw Error('As senhas não coincidem.');await V.create(password);lastActivity=Date.now();await renderWallet();toast('Carteira local criada. Faça um backup após registrar suas ajudas.');resumeRecord();}break;
 case'unlock-form':await V.unlock(String(d.get('password')));lastActivity=Date.now();await renderWallet();toast('Carteira aberta neste navegador.');resumeRecord();break;
 case'import-form':{if(!pendingImport)throw Error('Selecione um backup.');const replace=!!d.get('replace');await V.importBackup(pendingImport,String(d.get('password')),replace);pendingImport=null;lastActivity=Date.now();close();await renderWallet();toast('Backup importado e aberto. Nenhum pagamento foi confirmado.');resumeRecord();}break;
 case'eval-form':{if(V.locked)throw Error('A carteira foi bloqueada. Abra novamente para avaliar.');const x=readEval(form),rid=form.dataset.id;await V.mutate(s=>{const r=s.entries.find(k=>k.id===rid);if(!r)throw Error('Registro não encontrado.');r.xp=x;});lastActivity=Date.now();close();if(view==='carteira')await renderWallet();const s=X.score({...entry(rid)});toast(s.lock?'Avaliação salva: trava ativa, 0 XP.':`Avaliação salva: +${X.fmt(s.xp)} XP da Boa Ação.`);}break;
 case'record-form':{
  if(V.locked)throw Error('A carteira foi bloqueada. Abra novamente para registrar.');const cid=String(d.get('causeId')),date=String(d.get('date')),kind=String(d.get('kind')),detail=String(d.get('detail')).trim();if(!cause(cid))throw Error('Escolha uma instituição do catálogo.');if(!V.validDate(date)||date>today()||date<'1900-01-01')throw Error('Informe uma data válida, não futura.');if(!X.KINDS.includes(kind))throw Error('Tipo de ajuda inválido.');if(['materiais','tempo','divulgacao'].includes(kind)&&!detail)throw Error('Descreva a quantidade de materiais, o tempo dedicado ou a divulgação feita.');const amountCents=kind==='dinheiro'?C.cents(d.get('amount')):0;const xp=readEval(form);if(V.data.entries.some(r=>r.causeId===cid&&r.date===date&&r.kind===kind&&r.amountCents===amountCents)&&!await confirmDialog('Já existe um registro semelhante para esta instituição e data. É uma ajuda diferente que deve ser registrada?'))return;const evidence=await attachment(d.get('evidence'));const r={id:'BA-'+crypto.randomUUID(),causeId:cid,date,kind,amountCents,detail,createdAt:new Date().toISOString(),evidence,xp};await V.mutate(s=>s.entries.unshift(r));lastActivity=Date.now();close();if(view==='carteira')await renderWallet();const s=X.score(r);toast(s.lock?'Registro salvo. Trava ativa: 0 XP.':`Registro salvo: +${X.fmt(s.xp)} XP da Boa Ação.`);showReceipt(r.id);
 }break;
 case'suggest-form':{const url=new URL(String(d.get('url')));if(url.protocol!=='https:'||url.username||url.password||!url.hostname.includes('.'))throw Error('Informe um endereço HTTPS público de uma instituição, sem credenciais.');const s={type:'BA360-SUGESTAO',status:'PENDENTE_REVISAO_MANUAL',createdAt:new Date().toISOString(),institution:String(d.get('name')).trim(),officialWebsite:url.href,region:String(d.get('region')).trim(),category:String(d.get('category')),proposal:String(d.get('proposal')).trim(),note:'Ficha local. Não enviada nem publicada. Verificar existência, consentimento, prestação de contas e meios oficiais antes de incluir.'};download(JSON.stringify(s,null,2),'application/json','indicacao-de-instituicao-para-revisao.json');close();toast('Ficha preparada para download. Nada foi enviado ou publicado.');}break;
 }
 }catch(err){errorMessage(err);}finally{if(submit?.isConnected)submit.disabled=false;}});
document.addEventListener('change',async ev=>{const t=ev.target;if(t.id==='region'){region=t.value;renderCatalog();}if(t.id==='method'){method=t.value;renderCatalog();}if(t.id==='sort'){sort=t.value;renderCatalog();}if(t.id==='wallet-period'){period=t.value;renderWallet().catch(errorMessage);}if(t.id==='qp-value'){try{quick.amount=C.cents(t.value);renderQuickPix();}catch(err){t.value=moneyInput(quick.amount);errorMessage(err);}}
 if(t.id==='record-kind'||(t.name==='kind'&&t.form?.id==='calc-form')){const money=t.value==='dinheiro';const f=t.form;const amountField=f.querySelector('#record-amount-field');if(amountField){amountField.hidden=!money;amountField.querySelector('input').required=money;}const det=f.querySelector('textarea[name=detail]');if(det)det.required=['materiais','tempo','divulgacao'].includes(t.value);const rec=f.querySelector('.xp-received');if(rec)rec.hidden=!money;}
 if(t.name==='evidence'&&t.form?.id==='record-form'){const has=!!t.files?.length;const target=t.form.querySelector(`input[name=seguranca][value="${X.suggestSecurity(true,has)}"]`);if(target)target.checked=true;}
 if(t.form&&t.form.querySelector('.xp-preview'))previewXp(t.form);
 if(t.matches('.cart-amount')){try{cart.set(t.dataset.id,C.cents(t.value));await savePlan();renderSelection();syncCart();}catch(err){t.value=moneyInput(cart.get(t.dataset.id));errorMessage(err);}}});
document.addEventListener('input',ev=>{const f=ev.target.form;if(f&&f.querySelector('.xp-preview')&&ev.target.type!=='file')previewXp(f);});
$('#import-file').addEventListener('change',async ev=>{try{const file=ev.target.files?.[0];if(!file)return;if(file.size>25*1024*1024)throw Error('O backup deve ter no máximo 25 MB.');let envelope;try{envelope=JSON.parse(await file.text());V.validateEnvelope(envelope);}catch{throw Error('Arquivo inválido. Escolha um backup criptografado exportado por esta aplicação ou pelo app Bolsa Ajuda de Boa.');}pendingImport=envelope;hasVault=await V.exists();open(`<span class="dialog-kicker">RESTAURAÇÃO LOCAL</span><h2 id="dialog-title">Abrir seu backup.</h2><p class="dialog-text">O arquivo é lido somente neste navegador. A senha original é necessária para descriptografar.</p><form id="import-form" class="stack"><label class="form-field">Senha do backup<input type="password" name="password" minlength="12" maxlength="256" autocomplete="current-password" required></label>${hasVault?'<label class="check"><input type="checkbox" name="replace" required><span>Autorizo substituir a carteira salva neste navegador por este backup. Entendi que registros posteriores ao backup podem ser perdidos. Não haverá mesclagem automática.</span></label>':''}<div id="form-error" class="error-text" hidden></div><button class="btn primary full" type="submit">Descriptografar e importar</button></form>`);}catch(err){errorMessage(err);}});
$('#search').addEventListener('input',()=>{query=$('#search').value.trim();if(view==='explorar'||view==='favoritos')renderCatalog();});
$('#filter-toggle').addEventListener('click',()=>{const f=$('.filters');f.classList.toggle('open');$('#filter-toggle').setAttribute('aria-expanded',String(f.classList.contains('open')));});
dialog.addEventListener('cancel',()=>{content.innerHTML='';pendingImport=null;});
window.addEventListener('afterprint',()=>$('#print-area').innerHTML='');
window.addEventListener('hashchange',()=>{close();renderRoute();window.scrollTo({top:0});});
for(const event of ['keydown','pointerdown','input'])document.addEventListener(event,()=>lastActivity=Date.now(),{passive:true});
setInterval(()=>{if(!V.locked&&Date.now()-lastActivity>5*60*1000)lock();},15000);
window.addEventListener('pagehide',()=>{V.lock();$('#print-area').innerHTML='';});
window.addEventListener('pageshow',ev=>{if(ev.persisted){close();if(view==='carteira')renderWallet().catch(errorMessage);}});
renderRoute();
})();
